/* file : DTSimulationMapper.xml, id : getDTSimulationSharedList */ SELECT * FROM ( SELECT A.*, (SELECT DTL_CD_NM FROM TB_CODE_DTL T WHERE T.DEL_YN = 'N' AND T.GRP_CD = 'SIM_TYPE' AND T.DTL_CD = A.SIM_TP) SIM_TP_NM , (SELECT DTL_CD_NM FROM TB_CODE_DTL T WHERE T.DEL_YN = 'N' AND T.GRP_CD = 'AUGMENT_STATUS' AND T.DTL_CD = A.AUGMENT_STATUS) AUGMENT_STATUS_NM , (SELECT DTL_CD_NM FROM TB_CODE_DTL T WHERE T.DEL_YN = 'N' AND T.GRP_CD = 'AUGMENT_TYPE' AND T.DTL_CD = A.AUGMENT_TP) AUGMENT_TP_NM , (SELECT USER_ID FROM TB_USER U WHERE U.DEL_YN = 'N' AND U.USER_SEQ = A.REG_USER_SEQ) USER_ID FROM TB_META_AUGMENT A WHERE A.DEL_YN = 'N' AND A.RLS_YN = 'Y' AND (A.AUGMENT_STATUS = 'C' OR A.AUGMENT_STATUS = 'T') ) TB
