/* file : DTSimulationMapper.xml, id : getDTSimulationSharedList */ SELECT * FROM ( SELECT A.*, (SELECT DTL_CD_NM FROM TB_CODE_DTL T WHERE T.DEL_YN = 'N' AND T.GRP_CD = 'SIM_TYPE' AND T.DTL_CD = A.SIM_TP) SIM_TP_NM , (SELECT DTL_CD_NM FROM TB_CODE_DTL T WHERE T.DEL_YN = 'N' AND T.GRP_CD = 'AUGMENT_STATUS' AND T.DTL_CD = A.AUGMENT_STATUS) AUGMENT_STATUS_NM , (SELECT DTL_CD_NM FROM TB_CODE_DTL T WHERE T.DEL_YN = 'N' AND T.GRP_CD = 'AUGMENT_TYPE' AND T.DTL_CD = A.AUGMENT_TP) AUGMENT_TP_NM , (SELECT USER_ID FROM TB_USER U WHERE U.DEL_YN = 'N' AND U.USER_SEQ = A.REG_USER_SEQ) USER_ID FROM TB_META_AUGMENT A WHERE A.DEL_YN = 'N' AND A.RLS_YN = 'Y' AND (A.AUGMENT_STATUS = 'C' OR A.AUGMENT_STATUS = 'T' OR A.AUGMENT_STATUS = 'S') ) TB WHERE SIM_TP = #{sim_tp}
AND TITLE LIKE CONCAT('%', #{keyword}, '%')
/*||ORDER BY REG_DT DESC||*/

/* file : DTSimulationMapper.xml, id : getSimulationSetModelProperty */
SELECT *
FROM TB_META_USER_ITEM A
         JOIN TB_META_MODEL B ON A.MODEL_SEQ = B.MODEL_SEQ AND B.DEL_YN = 'N'
WHERE A.MODEL_SEQ = #{model_seq}

mapper.insert:
/* file : DTSimulationMapper.xml, id : getSimulationSaveAugment */
INSERT
INTO TB_META_AUGMENT ( AUGMENT_SEQ
                     , TITLE
                     , DERPN
                     , MODEL_SEQ
                     , AUGMENT_TP
                     , AUGMENT_STATUS
                     , SIM_TP
                     , CYCLE_TP
                     , CYCLE_END_TP
                     , CYCLE_END_DSGN_YMD
                     , CYCLE_BGNG_DSGN_YMD
                     , REG_USER_SEQ
                     , REG_IP
                     , DATA_CRT_LAST_HR
                     , USE_YN
                     , RLS_YN
                     , DATA_MAX_LIMIT_CNT
                     , DATA_CRT_BGNG_HR)
VALUES ( #{augment_seq}
       , #{title}
       , #{derpn}
       , #{model_seq}
       , #{augment_tp}
       , #{augment_status}
       , #{sim_tp}
       , #{cycle_tp}
       , #{cycle_end_tp}
       , #{cycle_end_dsgn_ymd}
       , #{cycle_bgng_dsgn_ymd}
       , #{user_seq}
       , #{user_ip}
       , #{data_crt_last_hr}
       , #{use_yn}
       , #{rls_yn}
       , #{data_max_limit_cnt}
       , #{data_crt_bgng_hr})

mapper.update:
/* file : DTModelMapper.xml, id : updateSimulationInfo */
UPDATE TB_META_AUGMENT
SET TITLE          = #{title}
  , DERPN          = #{derpn}
  , USE_YN         = #{useYn}
  , RLS_YN         = #{rlsYn}
  , AUGMENT_STATUS = #{augmentStatus}
  , MDFCN_DT       = CURRENT_TIMESTAMP
  , MDFCN_IP       = #{loginUserIp}
WHERE AUGMENT_SEQ = #{augmentSeq}
  AND DEL_YN = 'N'

