/* file : DTSimulationMapper.xml, id : getSimulationSaveAugment */
INSERT
INTO TB_META_AUGMENT (
AUGMENT_SEQ
, TITLE
, DERPN
, MODEL_SEQ
, AUGMENT_TP
, AUGMENT_STATUS
, SIM_TP
, CYCLE_BGNG_DSGN_YMD
, CYCLE_END_DSGN_YMD
, REG_USER_SEQ
, REG_IP
, USE_YN
, RLS_YN
)
VALUES (
#{augmentSeq}
, #{title}
, #{derpn}
, #{modelSeq}
, #{augmentTp}
, #{augmentStatus}
, #{simTp}
, #{cycleBgngDsgnYmd}
, #{cycleEndDsgnYmd}
, #{regUserSeq}
, #{regIp}
, #{useYn}
, #{rlsYn}
)

    SELECT LAST_INSERT_ID()

mapper.select:
/* file : DTSimulationMapper.xml, id : getDTSimulation */
SELECT A.*, B.MODEL_NM
FROM TB_META_AUGMENT A
         JOIN TB_META_MODEL B ON A.MODEL_SEQ = B.MODEL_SEQ AND B.USE_YN = 'Y' AND B.DEL_YN = 'N'
WHERE AUGMENT_SEQ = #{augment_seq}

/* file : DTSimulationMapper.xml, id : getDTSimulationFileList */
SELECT *
FROM TB_META_AUGMENT_FILES
WHERE AUGMENT_SEQ = #{augment_seq}
ORDER BY REG_DT DESC

/* file : DTSimulationMapper.xml, id : getModelInfo */
SELECT *
FROM TB_META_MODEL
WHERE MODEL_SEQ = #{modelSeq}
  AND USE_YN = 'Y'
  AND DEL_YN = 'N'

/* file : DTSimulationMapper.xml, id : getModelParams */
SELECT *,
       (SELECT MODEL_PARAMS_ITEM
        FROM TB_META_MODEL_ITEM B
        WHERE B.MODEL_ALGRM_SEQ = #{modelAlgrmSeq}
          AND A.MODEL_PARAMS_ITEM_SEQ = B.MODEL_PARAMS_ITEM_SEQ) MODEL_ALGRM_NM
FROM TB_META_MODEL_PARAMS A
WHERE MODEL_SEQ = #{modelSeq}
  AND USE_YN = 'Y'
  AND DEL_YN = 'N'

/* file : DTSimulationMapper.xml, id : getModelColumns */
SELECT *
FROM TB_META_MODEL_COLUMN
WHERE MODEL_SEQ = #{modelSeq}
  AND USE_YN = 'Y'
  AND DEL_YN = 'N'
